
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe_mol0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe_mol0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.311576333614241e+00, -3.249621550074432e+00, -3.162873215319204e+00, -3.042842869109171e+00, -2.879577616690873e+00, -2.662900334649801e+00, -2.385299644489561e+00, -2.047004331076736e+00, -1.661961290998359e+00, -1.256255666037362e+00, -8.480458643160987e-01, -5.721206877109259e-01, -4.976667004290260e-01, -4.095419618300587e-01, -2.975664968204303e-01, -1.906613982478380e-01, -1.022152013576490e-01, -3.727621101047246e-02, -8.110406642734002e-03, -9.121537402131921e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


